package cn.sixnine.filmlog;
public final class TimerStateTest {
 static void check(boolean value){if(!value)throw new AssertionError();}
 public static void main(String[] args){TimerState s=new TimerState();s.start(10000,100,3);check(!s.update(3100,3)&&s.remaining==7000);s.pause(4100,3);check(s.status.equals("paused")&&s.remaining==6000);s.update(999999,3);check(s.remaining==6000);s.resume(20000,3);check(s.due==26000);check(!s.update(25999,3));check(s.update(26000,3)&&s.status.equals("finished"));check(!s.update(27000,3));s.start(604800000,100,4);check(s.update(200,5)&&s.status.equals("interrupted"));s.start(1000,100,4);s.cancel();check(!s.update(9999,4)&&s.status.equals("cancelled"));s.start(10000,100,4);s.pause(200,4);check(s.update(300,5)&&s.status.equals("interrupted"));check(TimerState.duration(0).equals("0:00")&&TimerState.duration(-1).equals("0:00"));check(TimerState.duration(1).equals("0:01"));check(TimerState.duration(3600001).equals("1:00:01"));check(TimerState.duration(59999).equals("1:00"));check(TimerState.duration(3599000).equals("59:59"));check(TimerState.duration(3600000).equals("1:00:00"));try{s.start(0,0,1);throw new AssertionError();}catch(IllegalArgumentException expected){}System.out.println("PASS: monotonic deadline, pause/resume, late completion, reboot interruption, cancellation, duration bounds");}
}
